import{_ as e,r as s,o,c,e as a,a as l,s as r}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Контроллер форм - October CMS - 3.x","titleTemplate":false,"description":"Добавляет функции управления формами на любую страницу панели управления.","frontmatter":{"subtitle":"Добавляет функции управления формами на любую страницу панели управления."},"headers":[{"level":2,"title":"Настройка поведения формы","slug":"настроика-поведения-формы","link":"#настроика-поведения-формы","children":[{"level":3,"title":"Страница создания","slug":"страница-создания","link":"#страница-создания","children":[]},{"level":3,"title":"Страница обновления","slug":"страница-обновления","link":"#страница-обновления","children":[]},{"level":3,"title":"Страница предпросмотра","slug":"страница-предпросмотра","link":"#страница-предпросмотра","children":[]},{"level":3,"title":"Пользовательские сообщения","slug":"пользовательские-сообщения","link":"#пользовательские-сообщения","children":[]},{"level":3,"title":"Ограничение разрешениями","slug":"ограничение-разрешениями","link":"#ограничение-разрешениями","children":[]}]},{"level":2,"title":"Определение полей формы","slug":"определение-полеи-формы","link":"#определение-полеи-формы","children":[]},{"level":2,"title":"Представления формы","slug":"представления-формы","link":"#представления-формы","children":[{"level":3,"title":"Представление создания","slug":"представление-создания","link":"#представление-создания","children":[]},{"level":3,"title":"Представление обновления","slug":"представление-обновления","link":"#представление-обновления","children":[]},{"level":3,"title":"Представление предпросмотра","slug":"представление-предпросмотра","link":"#представление-предпросмотра","children":[]}]},{"level":2,"title":"Дизайны форм","slug":"дизаины-форм","link":"#дизаины-форм","children":[{"level":3,"title":"Режимы отображения","slug":"режимы-отображения","link":"#режимы-отображения","children":[]},{"level":3,"title":"Режим отображения во всплывающем окне","slug":"режим-отображения-во-всплывающем-окне","link":"#режим-отображения-во-всплывающем-окне","children":[]}]},{"level":2,"title":"Расширение поведения формы","slug":"расширение-поведения-формы","link":"#расширение-поведения-формы","children":[{"level":3,"title":"Расширение конфигурации формы","slug":"расширение-конфигурации-формы","link":"#расширение-конфигурации-формы","children":[]},{"level":3,"title":"Переопределение действия контроллера","slug":"переопределение-деиствия-контроллера","link":"#переопределение-деиствия-контроллера","children":[]},{"level":3,"title":"Переопределение данных сохранения формы","slug":"переопределение-данных-сохранения-формы","link":"#переопределение-данных-сохранения-формы","children":[]},{"level":3,"title":"Переопределение перенаправления контроллера","slug":"переопределение-перенаправления-контроллера","link":"#переопределение-перенаправления-контроллера","children":[]},{"level":3,"title":"Расширение запроса модели формы","slug":"расширение-запроса-модели-формы","link":"#расширение-запроса-модели-формы","children":[]},{"level":3,"title":"Расширение полей формы","slug":"расширение-полеи-формы","link":"#расширение-полеи-формы","children":[]},{"level":3,"title":"Фильтрация полей формы","slug":"фильтрация-полеи-формы","link":"#фильтрация-полеи-формы","children":[]}]},{"level":2,"title":"Валидация полей формы","slug":"валидация-полеи-формы","link":"#валидация-полеи-формы","children":[]}],"relativePath":"3.x/ru/extend/forms/form-controller.md","filePath":"3.x/ru/extend/forms/form-controller.md"}'),u={name:"3.x/ru/extend/forms/form-controller.md"};function i(k,n,d,g,m,h){const t=s("pre-heading"),p=s("post-heading");return o(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"Контроллер форм",-1)),a(p),n[1]||(n[1]=r(`<p>Класс <code>Backend\\Behaviors\\FormController</code> — это поведение контроллера, используемое для простого добавления функциональности форм на страницу панели управления. Поведение предоставляет три страницы: Создание, Обновление и Предпросмотр. Страница Предпросмотр является версией страницы Обновления только для чтения. При использовании поведения формы вам не нужно определять действия <code>create</code>, <code>update</code> и <code>preview</code> в контроллере — поведение делает это за вас. Однако вы должны предоставить соответствующие файлы представлений.</p><p>Поведение формы зависит от <a href="./../../element/form-fields.html">определений полей</a> формы и <a href="./../database/model.html">класса модели</a>. Для использования поведения формы вы должны добавить его в свойство <code>$implement</code> класса контроллера. Также должно быть определено свойство класса <code>$formConfig</code>, значение которого должно ссылаться на YAML-файл, используемый для настройки свойств поведения.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Categories</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>FormController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$formConfig</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;config_form.yaml&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>Очень часто контроллер формы и <a href="./../lists/list-controller.html">контроллер списка</a> используются вместе в одном контроллере.</p></div><h2 id="настроика-поведения-формы"><a href="#настроика-поведения-формы" class="header-anchor">#</a> Настройка поведения формы</h2><p>Файл конфигурации, указанный в свойстве <code>$formConfig</code>, определяется в формате YAML. Файл должен быть размещён в <a href="./../system/views.html">директории представлений контроллера</a>. Ниже приведён пример типичного файла конфигурации поведения формы.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_form.yaml</span>
<span class="token key atrule">name</span><span class="token punctuation">:</span> Blog Category
<span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/blog/models/post/fields.yaml
<span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Blog\\Post

<span class="token key atrule">create</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> New Blog Post

<span class="token key atrule">update</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Edit Blog Post

<span class="token key atrule">preview</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> View Blog Post
</code></pre></div><p>Следующие свойства обязательны в файле конфигурации формы.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>name</strong></td><td>имя объекта, управляемого этой формой.</td></tr><tr><td><strong>form</strong></td><td>массив конфигурации или ссылка на файл определения полей формы, см. <a href="./../../element/form-fields.html">поля формы</a>.</td></tr><tr><td><strong>modelClass</strong></td><td>имя класса модели, данные формы загружаются и сохраняются в эту модель.</td></tr></tbody></table></div><p>Перечисленные ниже свойства конфигурации являются необязательными. Определите их, если хотите, чтобы поведение формы поддерживало страницы Создание, Обновление или Предпросмотр.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>design</strong></td><td>отображать форму с использованием определённого режима дизайна при рендеринге (см. ниже).</td></tr><tr><td><strong>defaultRedirect</strong></td><td>используется как запасная страница перенаправления, если не определена конкретная страница перенаправления.</td></tr><tr><td><strong>create</strong></td><td>массив конфигурации или ссылка на файл конфигурации для страницы Создание.</td></tr><tr><td><strong>update</strong></td><td>массив конфигурации или ссылка на файл конфигурации для страницы Обновление.</td></tr><tr><td><strong>preview</strong></td><td>массив конфигурации или ссылка на файл конфигурации для страницы Предпросмотр.</td></tr><tr><td><strong>customMessages</strong></td><td>настройка сообщений, используемых в контроллере форм.</td></tr><tr><td><strong>permissions</strong></td><td>применение ограничений к определённым действиям, предоставляемым контроллером форм.</td></tr></tbody></table></div><h3 id="страница-создания"><a href="#страница-создания" class="header-anchor">#</a> Страница создания</h3><p>Для поддержки страницы Создание добавьте следующую конфигурацию в YAML-файл.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">create</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> New Blog Post
    <span class="token key atrule">redirect</span><span class="token punctuation">:</span> acme/blog/posts/update/<span class="token punctuation">:</span>id
    <span class="token key atrule">redirectClose</span><span class="token punctuation">:</span> acme/blog/posts
</code></pre></div><p>Для страницы Создание поддерживаются следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>заголовок страницы, может ссылаться на <a href="./../system/localization.html">строку локализации</a>.</td></tr><tr><td><strong>redirect</strong></td><td>страница перенаправления при сохранении записи.</td></tr><tr><td><strong>redirectClose</strong></td><td>страница перенаправления при сохранении записи и отправке переменной <strong>close</strong> с запросом.</td></tr><tr><td><strong>form</strong></td><td>переопределяет определения полей формы по умолчанию только для страницы создания.</td></tr></tbody></table></div><h3 id="страница-обновления"><a href="#страница-обновления" class="header-anchor">#</a> Страница обновления</h3><p>Для поддержки страницы Обновление добавьте следующую конфигурацию в YAML-файл.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">update</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Edit Blog Post
    <span class="token key atrule">redirect</span><span class="token punctuation">:</span> acme/blog/posts
</code></pre></div><p>Для страницы Обновление поддерживаются следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>заголовок страницы, может ссылаться на <a href="./../system/localization.html">строку локализации</a>.</td></tr><tr><td><strong>redirect</strong></td><td>страница перенаправления при сохранении записи.</td></tr><tr><td><strong>redirectClose</strong></td><td>страница перенаправления при сохранении записи и отправке переменной <strong>close</strong> с запросом.</td></tr><tr><td><strong>form</strong></td><td>переопределяет определения полей формы по умолчанию только для страницы обновления.</td></tr></tbody></table></div><h3 id="страница-предпросмотра"><a href="#страница-предпросмотра" class="header-anchor">#</a> Страница предпросмотра</h3><p>Для поддержки страницы Предпросмотр добавьте следующую конфигурацию в YAML-файл:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">preview</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> View Blog Post
</code></pre></div><p>Для страницы Предпросмотр поддерживаются следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>заголовок страницы, может ссылаться на <a href="./../system/localization.html">строку локализации</a>.</td></tr><tr><td><strong>form</strong></td><td>переопределяет определения полей формы по умолчанию только для страницы предпросмотра.</td></tr></tbody></table></div><h3 id="пользовательские-сообщения"><a href="#пользовательские-сообщения" class="header-anchor">#</a> Пользовательские сообщения</h3><p>Укажите свойство <code>customMessages</code> для переопределения сообщений по умолчанию, используемых контроллером форм. Значения могут быть обычным текстом или ссылаться на <a href="./../system/localization.html">строку локализации</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
    <span class="token key atrule">notFound</span><span class="token punctuation">:</span> Did not find the thing
    <span class="token key atrule">flashCreate</span><span class="token punctuation">:</span> New thing created
    <span class="token key atrule">flashUpdate</span><span class="token punctuation">:</span> Updated that thing
    <span class="token key atrule">flashDelete</span><span class="token punctuation">:</span> Thing is gone
</code></pre></div><p>Вы также можете изменять сообщения в контексте отображаемой формы. Следующий пример переопределит сообщение <code>notFound</code> только для контекста <code>update</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">update</span><span class="token punctuation">:</span>
    <span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
        <span class="token key atrule">notFound</span><span class="token punctuation">:</span> Nothing found when updating
</code></pre></div><p>Следующие сообщения доступны для переопределения.</p><details class="custom-block details"><summary>Просмотр списка доступных сообщений</summary><div class="table"><table tabindex="0"><thead><tr><th>Сообщение</th><th>Сообщение по умолчанию</th></tr></thead><tbody><tr><td><strong>notFound</strong></td><td>Form record with an ID of :id could not be found.</td></tr><tr><td><strong>flashCreate</strong></td><td>:name Created</td></tr><tr><td><strong>flashUpdate</strong></td><td>:name Updated</td></tr><tr><td><strong>flashDelete</strong></td><td>:name Deleted</td></tr></tbody></table></div></details><h3 id="ограничение-разрешениями"><a href="#ограничение-разрешениями" class="header-anchor">#</a> Ограничение разрешениями</h3><p>Укажите свойство <code>permissions</code> для применения ограничений к действиям, предоставляемым контроллером форм. Используйте <a href="./../backend/permissions.html">значения разрешений</a>, которые текущий пользователь панели управления должен иметь для использования поля. Поддерживается строка для одного разрешения или массив разрешений, из которых достаточно одного для предоставления доступа.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">permissions</span><span class="token punctuation">:</span>
    <span class="token key atrule">modelCreate</span><span class="token punctuation">:</span> admins.manage.create
    <span class="token key atrule">modelDelete</span><span class="token punctuation">:</span> admins.manage.delete
</code></pre></div><p>Следующие свойства доступны для переопределения в качестве необходимых разрешений.</p><details class="custom-block details"><summary>Просмотр списка доступных сообщений</summary><div class="table"><table tabindex="0"><thead><tr><th>Сообщение</th><th>Сообщение по умолчанию</th></tr></thead><tbody><tr><td><strong>modelCreate</strong></td><td>требуется для создания новых записей.</td></tr><tr><td><strong>modelUpdate</strong></td><td>требуется для изменения существующих записей.</td></tr><tr><td><strong>modelPreview</strong></td><td>требуется для предпросмотра существующих записей.</td></tr><tr><td><strong>modelDelete</strong></td><td>требуется для удаления существующих записей.</td></tr></tbody></table></div></details><h2 id="определение-полеи-формы"><a href="#определение-полеи-формы" class="header-anchor">#</a> Определение полей формы</h2><div class="custom-block aside"><p>Доступные свойства полей формы можно найти на странице <a href="./../../element/form-fields.html">определения полей формы</a>.</p></div><p>Поля формы определяются в YAML-файле. Конфигурация полей формы используется поведением формы для создания элементов управления формы и привязки их к полям модели.</p><p>Файл размещается в поддиректории директории <strong>models</strong> плагина. Имя поддиректории совпадает с именем класса модели в нижнем регистре. Имя файла не имеет значения, но <strong>fields.yaml</strong> и <strong>form_fields.yaml</strong> — распространённые имена. Пример расположения файла полей формы:</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           └── <code>models</code>
|               ├── post  <em>← Директория конфигурации</em>
|               |   └── fields.yaml  <em>← Файл конфигурации</em>
|               └── Post.php  <em>← Класс модели</em></p>
</code></pre><p>Поля могут быть размещены в трёх областях: <strong>внешняя область</strong>, <strong>основные вкладки</strong> или <strong>вторичные вкладки</strong>. Следующий пример показывает типичное содержимое файла определения полей формы.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># fields.yaml</span>
<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">blog_title</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Blog Title
        <span class="token key atrule">description</span><span class="token punctuation">:</span> The title for this blog

    <span class="token key atrule">published_at</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Published date
        <span class="token key atrule">description</span><span class="token punctuation">:</span> When this blog post was published
        <span class="token key atrule">type</span><span class="token punctuation">:</span> datepicker

    <span class="token comment"># [...]</span>

<span class="token key atrule">tabs</span><span class="token punctuation">:</span>
    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token comment"># [...]</span>

<span class="token key atrule">secondaryTabs</span><span class="token punctuation">:</span>
    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token comment"># [...]</span>
</code></pre></div><h2 id="представления-формы"><a href="#представления-формы" class="header-anchor">#</a> Представления формы</h2><p>Для каждой поддерживаемой формой страницы — Создание, Обновление и Предпросмотр — вы должны предоставить <a href="./../backend/controllers-ajax.html">файл представления</a> с соответствующим именем: <strong>create.php</strong>, <strong>update.php</strong> и <strong>preview.php</strong>.</p><p>Поведение формы добавляет два метода к классу контроллера: <code>formRender</code>, <code>formRenderDesign</code> и <code>formRenderPreview</code>. Эти методы рендерят элементы управления формы, настроенные с помощью описанного выше YAML-файла.</p><h3 id="представление-создания"><a href="#представление-создания" class="header-anchor">#</a> Представление создания</h3><p>Представление <strong>create.php</strong> представляет страницу Создание, позволяющую пользователям создавать новые записи. Типичная страница Создание содержит хлебные крошки, саму форму и кнопки формы. Атрибут <strong>data-request</strong> должен ссылаться на AJAX-обработчик <code>onSave</code>, предоставляемый поведением формы. Ниже приведено содержимое типичного файла представления создания.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;d-flex flex-column h-100&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>flex-grow-1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-buttons<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>loader-container<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
                <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSave<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-data</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ close: true }<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-message</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Creating Category...<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-hotkey</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>ctrl+enter, cmd+enter<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-default<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                Create and Close
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>span</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn-text<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                or <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/categories&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Cancel<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>span</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>Для отслеживания несохранённых изменений и отображения предупреждения при уходе со страницы формы добавьте атрибут <code>data-change-monitor</code> к открывающему тегу формы.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;...&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;data-change-monitor&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="представление-обновления"><a href="#представление-обновления" class="header-anchor">#</a> Представление обновления</h3><p>Представление <strong>update.php</strong> представляет страницу Обновление, позволяющую пользователям обновлять или удалять существующие записи. Типичная страница Обновление содержит хлебные крошки, саму форму и кнопки формы. Страница Обновление очень похожа на страницу Создание, но обычно имеет кнопку Удалить. Атрибут <strong>data-request</strong> должен ссылаться на AJAX-обработчик <code>onSave</code>, предоставляемый поведением формы. Ниже приведено содержимое типичного представления update.php.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;d-flex flex-column h-100&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>flex-grow-1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-buttons<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>loader-container<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
                <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSave<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-data</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ close: true }<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-message</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Saving Category...<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-hotkey</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>ctrl+enter, cmd+enter<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-default<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                Save and Close
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
                <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>oc-icon-trash-o btn-icon danger pull-right<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDelete<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-message</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Deleting Category...<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-confirm</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Do you really want to delete this category?<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>span</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn-text<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                or <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/categories&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Cancel<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>span</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="представление-предпросмотра"><a href="#представление-предпросмотра" class="header-anchor">#</a> Представление предпросмотра</h3><p>Представление <strong>preview.php</strong> представляет страницу Предпросмотр, позволяющую пользователям просматривать существующие записи в режиме только для чтения. Типичная страница Предпросмотр содержит хлебные крошки и саму форму. Ниже приведено содержимое типичного представления preview.php.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-preview<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRenderPreview</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="дизаины-форм"><a href="#дизаины-форм" class="header-anchor">#</a> Дизайны форм</h2><p>Команда <code>create:controller</code> генерирует <a href="./../system/controllers.html">контроллер</a> и поддерживает опцию <code>--design</code> для реализации желаемого режима отображения, как описано ниже.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:controller Acme.Blog Posts <span class="token parameter variable">--design</span><span class="token operator">=</span>popup
</code></pre></div><p>Дизайны форм полезны, когда нужно отображать форму без управления HTML-содержимым, что менее гибко, но может ускорить процесс создания форм.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">design</span><span class="token punctuation">:</span>
    <span class="token key atrule">displayMode</span><span class="token punctuation">:</span> basic
</code></pre></div><p>Свойство <strong>design</strong> в конфигурации поведения контролирует отображение формы. Поддерживаются следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>displayMode</strong></td><td>указывает используемый режим отображения, поддерживаемые значения: <code>custom</code>, <code>basic</code>, <code>survey</code>, <code>sidebar</code>, <code>popup</code>. По умолчанию: <code>basic</code></td></tr><tr><td><strong>horizontalMode</strong></td><td>показывать поля формы в горизонтальной ориентации. По умолчанию: <code>false</code></td></tr><tr><td><strong>surveyMode</strong></td><td>отключает вкладки и отображает все поля на странице в секциях с заголовками. По умолчанию: <code>false</code></td></tr><tr><td><strong>size</strong></td><td>размер контейнера страницы, поддерживаемые значения: шаг <code>50</code> между <code>400</code>-<code>1200</code>, <code>auto</code>. По умолчанию: <code>auto</code></td></tr><tr><td><strong>sidebarSize</strong></td><td>ширина боковой панели в режиме <code>sidebar</code>, поддерживаемые значения: шаг <code>50</code> между <code>300</code>-<code>750</code>. По умолчанию: <code>300</code></td></tr></tbody></table></div><p>Используйте метод <code>formRenderDesign</code> для рендеринга дизайна формы внутри файлов представлений <strong>create.php</strong>, <strong>update.php</strong> и <strong>preview.php</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRenderDesign</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="режимы-отображения"><a href="#режимы-отображения" class="header-anchor">#</a> Режимы отображения</h3><p>При использовании режима отображения <strong>design</strong> в конфигурации поведения содержимое представлений генерируется с использованием стандартного содержимого форм, предоставляемого системой.</p><p>Поддерживаются следующие значения <strong>displayMode</strong> с описаниями.</p><div class="table"><table tabindex="0"><thead><tr><th>Режим отображения</th><th>Описание</th></tr></thead><tbody><tr><td><strong>custom</strong></td><td>Рендеринг формы с использованием пользовательских файлов представлений (по умолчанию)</td></tr><tr><td><strong>basic</strong></td><td>Базовый макет для стандартных форм</td></tr><tr><td><strong>survey</strong></td><td>Макет опроса с использованием наложенных секций с заголовками</td></tr><tr><td><strong>sidebar</strong></td><td>Макет с боковой панелью, где вторичные вкладки рендерятся в боковой панели</td></tr><tr><td><strong>popup</strong></td><td>Содержимое формы управляется внутри всплывающих окон</td></tr></tbody></table></div><p>Свойство <strong>size</strong> определяет размер контейнера страницы или размер всплывающего окна.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">design</span><span class="token punctuation">:</span>
    <span class="token key atrule">displayMode</span><span class="token punctuation">:</span> survey
    <span class="token key atrule">size</span><span class="token punctuation">:</span> <span class="token number">950</span>
</code></pre></div><h3 id="режим-отображения-во-всплывающем-окне"><a href="#режим-отображения-во-всплывающем-окне" class="header-anchor">#</a> Режим отображения во всплывающем окне</h3><p>Если <strong>design</strong> установлен на использование режима отображения <code>popup</code>, вам вообще не нужно создавать файлы представлений. Все функции управления формой содержатся внутри всплывающего окна.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">design</span><span class="token punctuation">:</span>
    <span class="token key atrule">displayMode</span><span class="token punctuation">:</span> popup
    <span class="token key atrule">size</span><span class="token punctuation">:</span> <span class="token number">750</span>
</code></pre></div><p>При интеграции с <a href="./../lists/list-controller.html">контроллером списка</a> установите свойство <strong>recordOnClick</strong> в <code>popup</code>, чтобы открывать представление управления при клике на запись.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_list.yaml</span>
<span class="token key atrule">recordOnClick</span><span class="token punctuation">:</span> popup
</code></pre></div><p><strong>recordOnClick</strong> также поддерживает передачу контекста в контроллер форм, например, установите значение <code>popup@preview</code> для контекста предпросмотра.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_list.yaml</span>
<span class="token key atrule">recordOnClick</span><span class="token punctuation">:</span> popup@preview
</code></pre></div><p>Представление создания можно открыть с помощью AJAX-обработчика <code>onLoadPopupForm</code> в сочетании с элементом управления popup, как в примере ниже.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>popup<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-handler</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onLoadPopupForm<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-primary<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    New Item
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="расширение-поведения-формы"><a href="#расширение-поведения-формы" class="header-anchor">#</a> Расширение поведения формы</h2><p>Иногда вам может потребоваться изменить поведение формы по умолчанию, и для этого существует несколько способов.</p><h3 id="расширение-конфигурации-формы"><a href="#расширение-конфигурации-формы" class="header-anchor">#</a> Расширение конфигурации формы</h3><p>Вы можете динамически расширить конфигурацию формы с помощью метода <code>formGetConfig</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">formGetConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$config</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;FormController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">formGetConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$config</span><span class="token operator">-&gt;</span><span class="token property">form</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makeConfig</span><span class="token punctuation">(</span><span class="token variable">$config</span><span class="token operator">-&gt;</span><span class="token property">form</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Set the active tab dynamically</span>
    <span class="token variable">$config</span><span class="token operator">-&gt;</span><span class="token property">form</span><span class="token operator">-&gt;</span><span class="token property">tabs</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;activeTab&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Activities&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token variable">$config</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="переопределение-деиствия-контроллера"><a href="#переопределение-деиствия-контроллера" class="header-anchor">#</a> Переопределение действия контроллера</h3><p>Вы можете использовать собственную логику для метода действия <code>create</code>, <code>update</code> или <code>preview</code> в контроллере, а затем опционально вызвать родительский метод поведения формы.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">update</span><span class="token punctuation">(</span><span class="token variable">$recordId</span><span class="token punctuation">,</span> <span class="token variable">$context</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">//</span>
    <span class="token comment">// Do any custom code here</span>
    <span class="token comment">//</span>

    <span class="token comment">// Call the FormController behavior update() method</span>
    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;FormController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token variable">$recordId</span><span class="token punctuation">,</span> <span class="token variable">$context</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="переопределение-данных-сохранения-формы"><a href="#переопределение-данных-сохранения-формы" class="header-anchor">#</a> Переопределение данных сохранения формы</h3><p>Вы можете использовать переопределение <code>formBeforeSave</code> (или эквивалентное) для изменения значений формы перед сохранением или обновлением. Для переопределения значения поля используйте метод <code>formSetSaveValue(key, value)</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">formBeforeSave</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// When locale dropdown is set to &quot;custom&quot;, override with the _custom_locale text field</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;MyModel[locale]&#39;</span><span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;custom&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formSetSaveValue</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;locale&#39;</span><span class="token punctuation">,</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;MyModel[_custom_locale]&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="переопределение-перенаправления-контроллера"><a href="#переопределение-перенаправления-контроллера" class="header-anchor">#</a> Переопределение перенаправления контроллера</h3><p>Вы можете указать URL для перенаправления после сохранения модели, переопределив метод <code>formGetRedirectUrl</code>. Этот метод возвращает адрес для перенаправления, где относительные URL считаются URL панели управления.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">formGetRedirectUrl</span><span class="token punctuation">(</span><span class="token variable">$context</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">,</span> <span class="token variable">$model</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;https://octobercms.com&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="расширение-запроса-модели-формы"><a href="#расширение-запроса-модели-формы" class="header-anchor">#</a> Расширение запроса модели формы</h3><p>Запрос поиска для <a href="./../database/model.html">модели базы данных</a> формы может быть расширен путём переопределения метода <code>formExtendQuery</code> внутри класса контроллера. Этот пример гарантирует, что мягко удалённые записи всё ещё могут быть найдены и обновлены, применяя область видимости <strong>withTrashed</strong> к запросу:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">formExtendQuery</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="расширение-полеи-формы"><a href="#расширение-полеи-формы" class="header-anchor">#</a> Расширение полей формы</h3><p>Вы можете расширить поля другого контроллера извне, привязавшись к <a href="./../services/event.html">глобальному событию</a> <code>backend.form.extendFields</code>. Функция события получит аргумент <code>$form</code>, представляющий объект <code>Backend\\Widgets\\Form</code>, где вы можете использовать методы <code>getController</code>, <code>getModel</code> и <code>getContext</code> для проверки контекста выполнения.</p><p>Поскольку это событие может повлиять на все формы, важно проверить, что контроллер и модель имеют правильный тип. Вот пример использования метода <code>addFields</code> для добавления новых полей в форму настроек почты.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.form.extendFields&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$form</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>
        <span class="token operator">!</span><span class="token variable">$form</span><span class="token operator">-&gt;</span><span class="token function">getController</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>Settings</span> <span class="token operator">||</span>
        <span class="token operator">!</span><span class="token variable">$form</span><span class="token operator">-&gt;</span><span class="token function">getModel</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>MailSetting</span>
    <span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token variable">$form</span><span class="token operator">-&gt;</span><span class="token function">addFields</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;my_field&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;My Field&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is a custom field I have added.&#39;</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете расширить поля формы внутренне, переопределив метод <code>formExtendFields</code> внутри класса контроллера. Это повлияет только на форму, используемую поведением <code>FormController</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Categories</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>FormController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">formExtendFields</span><span class="token punctuation">(</span><span class="token variable">$form</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$form</span><span class="token operator">-&gt;</span><span class="token function">addFields</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>На объекте <code>$form</code> доступны следующие методы.</p><div class="table"><table tabindex="0"><thead><tr><th>Метод</th><th>Описание</th></tr></thead><tbody><tr><td><strong>addFields</strong></td><td>добавляет новые поля во внешнюю область</td></tr><tr><td><strong>addTabFields</strong></td><td>добавляет новые поля в область вкладок</td></tr><tr><td><strong>addSecondaryTabFields</strong></td><td>добавляет новые поля в область вторичных вкладок</td></tr><tr><td><strong>removeField</strong></td><td>удаляет поле из любой области</td></tr></tbody></table></div><p>Каждый метод принимает массив полей, аналогичный <a href="./../../element/form-fields.html">конфигурации полей формы</a>.</p><h3 id="фильтрация-полеи-формы"><a href="#фильтрация-полеи-формы" class="header-anchor">#</a> Фильтрация полей формы</h3><p>Как описано в <a href="./field-dependencies.html">разделе зависимостей полей</a>, вы также можете реализовать фильтрацию полей формы через расширение, подключившись к событию <code>form.filterFields</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.form.filterFields&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$formWidget</span><span class="token punctuation">,</span> <span class="token variable">$fields</span><span class="token punctuation">,</span> <span class="token variable">$context</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">source_type</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;http&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">source_url</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">git_branch</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token keyword">elseif</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">source_type</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;git&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">source_url</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">git_branch</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token keyword">else</span> <span class="token punctuation">{</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">source_url</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">git_branch</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="валидация-полеи-формы"><a href="#валидация-полеи-формы" class="header-anchor">#</a> Валидация полей формы</h2><p>Для валидации полей вашей формы вы можете использовать <a href="./../database/traits.html">трейт Validation</a> в вашей модели.</p>`,114))])}const y=e(u,[["render",i]]);export{v as __pageData,y as default};
